import { Component } from '@angular/core';
import { Form, GenericFormComponent } from "../../../shared/generic-form/generic-form.component";
import { TipoDiscapacidad } from '../../../models/tipo.discapacidad';
import { TipoDiscapacidadService } from '../../../controllers/tipo.discapacidad.service';
import { ActivatedRoute } from '@angular/router';
import { UtilsService } from '../../../services/utils.service';

const FORM_DEF:Form=[
  {
    key:'nombre',
    label:'Tipo de Discapacidad',
    type:'text',
    style:{
      div:'col-12 p-3'
    }
  }
]

@Component({
    selector: 'app-form-tipos-discapacidad',
    imports: [
        GenericFormComponent
    ],
    templateUrl: './form-tipos-discapacidad.component.html',
    styleUrl: './form-tipos-discapacidad.component.css'
})
export class FormTiposDiscapacidadComponent {
  discapacidad?:TipoDiscapacidad
  form= FORM_DEF
  constructor(
    public tipoDiscapacidadController:TipoDiscapacidadService,
    private route: ActivatedRoute,
    private utils: UtilsService,
  ){}

  ngOnInit(){
    this.route.paramMap.subscribe(async (params)=>{
      const id = this.utils.intOrNull(params.get('etnia_id'))
      if(id){
        this.discapacidad=await this.tipoDiscapacidadController.find(id)
      }
    })
  }
}
